// lib/services/local_emergency_store.dart
//
// SafeReach — Local Offline Emergency Store (Hive)
// Package: com.example.safereach
//
// Design rules followed:
//   Rule #2  — GPS coordinates cached locally, independent of map SDK.
//   Rule #6  — Single broadcast StreamController; no duplicate listeners.
//   Rule #7  — IDs are EMG-2026-XXXXXXXX, generated by Emergency.generateId().
//   Rule #8  — Every write is local-first; syncStatus tracks the queue state.

import 'dart:async';
import 'dart:convert';

import 'package:hive_flutter/hive_flutter.dart';

import '../models/emergency.dart';

// ---------------------------------------------------------------------------
// Sync-status constants
// ---------------------------------------------------------------------------

/// The sync status values stored alongside every persisted [Emergency].
/// These are plain strings so they survive schema migrations without code-gen.
abstract class SyncStatus {
  SyncStatus._();

  /// Written locally; not yet uploaded to Firestore.
  static const String pending = 'pending';

  /// Successfully written to Firestore.
  static const String synced = 'synced';

  /// Upload attempted but failed (will be retried by the sync worker).
  static const String failed = 'failed';
}

// ---------------------------------------------------------------------------
// Hive box key constants
// ---------------------------------------------------------------------------

abstract class _HiveKeys {
  _HiveKeys._();

  static const String emergenciesBox = 'emergencies_box';
  static const String metaBox = 'meta_box';

  // Keys inside metaBox
  static const String lastKnownLat = 'last_known_lat';
  static const String lastKnownLng = 'last_known_lng';
  static const String lastKnownAccuracy = 'last_known_accuracy';
}

// ---------------------------------------------------------------------------
// Wrapper stored in Hive per emergency
// ---------------------------------------------------------------------------

/// Internal envelope stored in the Hive box.
/// Keeps the [Emergency] JSON alongside its [syncStatus] and
/// the UTC timestamp of the most recent local write.
class _EmergencyEnvelope {
  final Map<String, dynamic> emergencyJson;
  final String syncStatus;
  final String lastModifiedLocal; // ISO-8601 UTC

  _EmergencyEnvelope({
    required this.emergencyJson,
    required this.syncStatus,
    required this.lastModifiedLocal,
  });

  Map<String, dynamic> toMap() => {
        'emergencyJson': emergencyJson,
        'syncStatus': syncStatus,
        'lastModifiedLocal': lastModifiedLocal,
      };

  factory _EmergencyEnvelope.fromMap(Map<dynamic, dynamic> map) =>
      _EmergencyEnvelope(
        emergencyJson:
            Map<String, dynamic>.from(map['emergencyJson'] as Map),
        syncStatus: map['syncStatus'] as String,
        lastModifiedLocal: map['lastModifiedLocal'] as String,
      );
}

// ---------------------------------------------------------------------------
// LocalEmergencyStore
// ---------------------------------------------------------------------------

/// Offline-first local store for [Emergency] records backed by Hive.
///
/// Usage:
/// ```dart
/// final store = LocalEmergencyStore();
/// await store.init();
/// ```
///
/// One instance should be created at app startup and kept alive for the
/// app's lifetime (managed by the [localStoreProvider] Riverpod provider).
class LocalEmergencyStore {
  Box? _emergenciesBox;
  Box? _metaBox;

  // Single broadcast controller (Rule #6 — never duplicated).
  // Maps emergencyId → its controller.
  final Map<String, StreamController<Emergency?>> _controllers = {};

  // ---------------------------------------------------------------------------
  // Lifecycle
  // ---------------------------------------------------------------------------

  /// Opens Hive boxes. Must be awaited before any other method is called.
  Future<void> init() async {
    await Hive.initFlutter();
    _emergenciesBox = await Hive.openBox(_HiveKeys.emergenciesBox);
    _metaBox = await Hive.openBox(_HiveKeys.metaBox);
  }

  /// Closes all Hive boxes and broadcast stream controllers.
  /// Call this when the store is being disposed (via Riverpod [ref.onDispose]).
  Future<void> dispose() async {
    for (final ctrl in _controllers.values) {
      await ctrl.close();
    }
    _controllers.clear();
    await _emergenciesBox?.close();
    await _metaBox?.close();
  }

  Box get _emergencies {
    assert(_emergenciesBox != null,
        'LocalEmergencyStore.init() must be called before use.');
    return _emergenciesBox!;
  }

  Box get _meta {
    assert(_metaBox != null,
        'LocalEmergencyStore.init() must be called before use.');
    return _metaBox!;
  }

  // ---------------------------------------------------------------------------
  // Write
  // ---------------------------------------------------------------------------

  /// Persists [emergency] to the local Hive box with the given [syncStatus].
  ///
  /// Always writes locally first (Rule #8 — offline queue).
  /// Notifies any active [watchEmergency] stream.
  Future<void> saveEmergency(
    Emergency emergency, {
    String syncStatus = SyncStatus.pending,
  }) async {
    final envelope = _EmergencyEnvelope(
      emergencyJson: emergency.toJson(),
      syncStatus: syncStatus,
      lastModifiedLocal: DateTime.now().toUtc().toIso8601String(),
    );

    // Hive requires values to be JSON-encodable primitives when not using
    // type adapters; we store the envelope as a JSON string to stay
    // adapter-free and schema-migration-safe.
    await _emergencies.put(emergency.id, jsonEncode(envelope.toMap()));

    // Push update to any active watcher for this id (Rule #6).
    _controllers[emergency.id]?.add(emergency);
  }

  /// Marks an already-persisted emergency as synced with Firestore.
  Future<void> markAsSynced(String id) async {
    final existing = _rawEnvelope(id);
    if (existing == null) return;

    final updated = _EmergencyEnvelope(
      emergencyJson: existing.emergencyJson,
      syncStatus: SyncStatus.synced,
      lastModifiedLocal: DateTime.now().toUtc().toIso8601String(),
    );
    await _emergencies.put(id, jsonEncode(updated.toMap()));
  }

  /// Marks a sync attempt as failed so the sync worker will retry later.
  Future<void> markAsFailed(String id) async {
    final existing = _rawEnvelope(id);
    if (existing == null) return;

    final updated = _EmergencyEnvelope(
      emergencyJson: existing.emergencyJson,
      syncStatus: SyncStatus.failed,
      lastModifiedLocal: DateTime.now().toUtc().toIso8601String(),
    );
    await _emergencies.put(id, jsonEncode(updated.toMap()));
  }

  // ---------------------------------------------------------------------------
  // Read
  // ---------------------------------------------------------------------------

  /// Returns the persisted [Emergency] for [id], or `null` if not found.
  Emergency? getEmergencyById(String id) {
    final env = _rawEnvelope(id);
    if (env == null) return null;
    return Emergency.fromJson(env.emergencyJson);
  }

  /// Returns all persisted emergencies, newest-first (by `createdAt`).
  List<Emergency> getAllEmergencies() {
    return _emergencies.keys
        .map((key) => _rawEnvelope(key as String))
        .whereType<_EmergencyEnvelope>()
        .map((env) => Emergency.fromJson(env.emergencyJson))
        .toList()
      ..sort((a, b) => b.createdAt.compareTo(a.createdAt));
  }

  /// Returns all emergencies whose [syncStatus] is [SyncStatus.pending]
  /// or [SyncStatus.failed] — i.e., not yet confirmed synced to Firestore.
  /// Used by the sync worker (Phase 3) to drain the offline queue.
  List<Emergency> getPendingSyncEmergencies() {
    return _emergencies.keys
        .map((key) => _rawEnvelope(key as String))
        .whereType<_EmergencyEnvelope>()
        .where((env) =>
            env.syncStatus == SyncStatus.pending ||
            env.syncStatus == SyncStatus.failed)
        .map((env) => Emergency.fromJson(env.emergencyJson))
        .toList();
  }

  /// Returns the [syncStatus] string for [id], or `null` if the id is unknown.
  String? getSyncStatus(String id) => _rawEnvelope(id)?.syncStatus;

  // ---------------------------------------------------------------------------
  // Watch (single-lifecycle broadcast stream, Rule #6)
  // ---------------------------------------------------------------------------

  /// Returns a broadcast [Stream] that emits the latest [Emergency] for [id]
  /// whenever it changes, or `null` if the record does not exist.
  ///
  /// A single [StreamController] is created per id and reused for all
  /// listeners — it is never duplicated (Rule #6). The controller is closed
  /// when [dispose()] is called.
  Stream<Emergency?> watchEmergency(String id) {
    if (!_controllers.containsKey(id)) {
      _controllers[id] = StreamController<Emergency?>.broadcast();
    }
    // Seed the stream with the current value so new subscribers get immediate state.
    final ctrl = _controllers[id]!;
    final current = getEmergencyById(id);
    // Schedule the seed after the stream is returned so the subscriber
    // is already attached when the event fires.
    Future.microtask(() {
      if (!ctrl.isClosed) ctrl.add(current);
    });
    return ctrl.stream;
  }

  // ---------------------------------------------------------------------------
  // Last-known location cache (Rule #2 — offline GPS fallback)
  // ---------------------------------------------------------------------------

  /// Caches the most recently obtained GPS fix so it is available instantly
  /// on next app start even before a fresh GPS lock is acquired.
  Future<void> cacheLastKnownLocation(
    double lat,
    double lng,
    double? accuracy,
  ) async {
    await _meta.put(_HiveKeys.lastKnownLat, lat);
    await _meta.put(_HiveKeys.lastKnownLng, lng);
    await _meta.put(_HiveKeys.lastKnownAccuracy, accuracy);
  }

  /// Returns the last cached GPS fix as a map with keys
  /// `latitude`, `longitude`, `accuracyMeters`, or `null` if none cached.
  Map<String, double?>? getLastKnownLocation() {
    final lat = _meta.get(_HiveKeys.lastKnownLat) as double?;
    final lng = _meta.get(_HiveKeys.lastKnownLng) as double?;
    if (lat == null || lng == null) return null;
    final accuracy = _meta.get(_HiveKeys.lastKnownAccuracy) as double?;
    return {
      'latitude': lat,
      'longitude': lng,
      'accuracyMeters': accuracy,
    };
  }

  // ---------------------------------------------------------------------------
  // Internal helpers
  // ---------------------------------------------------------------------------

  _EmergencyEnvelope? _rawEnvelope(String id) {
    final raw = _emergencies.get(id);
    if (raw == null) return null;
    try {
      final map = jsonDecode(raw as String) as Map<dynamic, dynamic>;
      return _EmergencyEnvelope.fromMap(map);
    } catch (_) {
      return null;
    }
  }
}

